	b := &ReportBuilder{}
	_, err := b.Build()
	check(err != nil)
	first, err := b.Title("Design").Section("Intent").Build()
	check(err == nil)
	b.Section("Tests")
	second, err := b.Build()
	check(err == nil)
	first.Sections[0] = "changed"
	check(len(first.Sections) == 1 && len(second.Sections) == 2)
	check(second.Sections[0] == "Intent")
	fmt.Println("OK builder")
}

