func (r *Rule) Handle(value int) bool {
	return r.accepts(value) && (r.next == nil || r.next.Handle(value))
}

func main() {
	visits := 0
	chain := &Rule{func(n int) bool { return n > 0 }, &Rule{func(n int) bool { visits++; return n < 10 }, nil}}
